'use strict';
const B_DOMAINS={Identidade:{title:'Quem participa.',copy:'Pessoas, organizações, credenciais e permissões acompanham o contexto de cada interação.',input:'Contexto de acesso',output:'Identidade e escopo',tone:'identity'},Comunicação:{title:'Onde a experiência acontece.',copy:'Canais conectam pessoas e operações. A conversa participa da jornada sem absorver todas as regras do produto.',input:'Mensagem ou encontro',output:'Interação conectada',tone:'communication'},Financeiro:{title:'O dinheiro tem responsabilidades próprias.',copy:'Contas, cálculos, parâmetros e operações financeiras participam da composição com contratos distintos.',input:'Contexto financeiro',output:'Operação ou condição',tone:'finance'},Dados:{title:'Informação com contexto.',copy:'Fontes e registros oferecem os dados de que a jornada precisa, preservando sua responsabilidade no conjunto.',input:'Fonte ou informação',output:'Contexto organizado',tone:'data'},Decisão:{title:'Regras que encontram o contexto.',copy:'A política e a orquestração trabalham juntas com papéis distintos: avaliar uma regra e organizar o percurso.',input:'Dados da jornada',output:'Resposta da avaliação',tone:'decision'},Documentos:{title:'O registro também tem uma jornada.',copy:'Gerar, guardar, assinar e confirmar são responsabilidades diferentes, conectadas ao trabalho do produto.',input:'Conteúdo ou evidência',output:'Documento ou registro',tone:'document'},Produtividade:{title:'O próximo encontro começa na disponibilidade.',copy:'A organização do tempo pode participar de consultas, entrevistas e reuniões sem precisar ser refeita a cada produto.',input:'Pessoas e horários',output:'Disponibilidade e encontro',tone:'calendar'},Plataforma:{title:'Uma operação que você pode acompanhar.',copy:'Configuração, eventos, registros e observação sustentam a evolução do produto com responsabilidades explícitas.',input:'Estado da operação',output:'Controle e acompanhamento',tone:'platform'},Inteligência:{title:'Inteligência conectada ao trabalho.',copy:'Texto, imagem e áudio participam de tarefas com contexto. As ações continuam sujeitas ao papel definido para cada jornada.',input:'Conteúdo e contexto',output:'Informação trabalhada',tone:'intelligence'},Comércio:{title:'O comércio encontra uma base.',copy:'Catálogo, estoque, preço e pedido participam de uma operação comercial por capacidades que podem ser combinadas.',input:'Produto ou pedido',output:'Operação comercial',tone:'commerce'}};
function bDomain(cat){return B_DOMAINS[cat]||B_DOMAINS.Plataforma}
function bGlyph(cat,id='domain'){const tone=bDomain(cat).tone;let shapes='';if(tone==='identity'){shapes=`${[65,90,115,140,165].map((r,i)=>`<ellipse class="identity-ring ir-${i}" cx="250" cy="220" rx="${r}" ry="${r*.75}" fill="none" stroke="${i===2?'#e9873c':'#9772b2'}" stroke-width="${i===2?2:1}"/>`).join('')}<path d="M250 110L345 164V277L250 332L155 277V164Z" fill="none" stroke="#734b9c"/><circle cx="250" cy="220" r="29" fill="#734b9c"/><path d="M238 221L247 230L264 212" stroke="#f6f3ee" fill="none" stroke-width="2"/>`}
else if(tone==='communication'){shapes=`<g class="glyph-channel"><path d="M110 153L318 106V239L251 255L218 305V263L110 287Z" fill="#9f7bbc"/><path d="M169 186L379 140V290L286 310L246 350V318L169 335Z" fill="#e9dfef" stroke="#734b9c"/><path d="M205 222L337 194M205 247L308 225M205 272L326 245" stroke="#9573ac"/><circle cx="330" cy="120" r="18" fill="#ef873e"/></g>`}
else if(tone==='finance'||tone==='commerce'){shapes=`<g class="glyph-finance"><circle cx="250" cy="220" r="130" fill="none" stroke="#cbbbd5"/><circle cx="250" cy="220" r="104" fill="none" stroke="#734b9c" stroke-width="44" stroke-dasharray="430 224" transform="rotate(-90 250 220)"/><circle cx="250" cy="220" r="104" fill="none" stroke="#ef873e" stroke-width="44" stroke-dasharray="110 544" transform="rotate(160 250 220)"/><circle cx="250" cy="220" r="54" fill="#e5d9ed"/><path d="M230 221H270M250 201V241" stroke="#734b9c" stroke-width="2"/></g><path d="M85 355H415M85 355V330" fill="none" stroke="#b29bc2"/>`}
else if(tone==='data'||tone==='document'){shapes=`<g class="glyph-data">${[2,1,0].map(i=>`<g class="data-layer dl-${i}"><path d="M95 ${150+i*60}L285 ${80+i*60}L405 ${150+i*60}L215 ${220+i*60}Z" fill="${i===1?'#734b9c':'#eee6f3'}" stroke="#9a78b2"/><path d="M95 ${150+i*60}V${164+i*60}L215 ${234+i*60}V${220+i*60}Z" fill="#c0a6d1"/><path d="M215 ${220+i*60}L405 ${150+i*60}V${164+i*60}L215 ${234+i*60}Z" fill="#a886c0"/></g>`).join('')}<path d="M180 147L290 107M210 165L320 125" stroke="#bc9bce"/><circle cx="373" cy="280" r="18" fill="#ef873e"/></g>`}
else if(tone==='decision'){shapes=`<path d="M62 220H150L250 110H360L430 220M150 220L250 330H360L430 220" fill="none" stroke="#bda6cb"/><path class="decision-path" d="M62 220H150L250 110H360L430 220" fill="none" stroke="#734b9c" stroke-width="3"/><path d="M250 55L337 110L250 165L163 110Z" fill="#734b9c"/><path d="M250 82L295 110L250 138L205 110Z" fill="none" stroke="#d5bee5"/><circle cx="430" cy="220" r="25" fill="#ef873e"/><circle cx="62" cy="220" r="13" fill="#bba0ce"/>`}
else if(tone==='calendar'){shapes=`<g class="glyph-calendar"><path d="M130 98H370V345H130Z" fill="#ebe2f1" stroke="#9c7ab6"/><path d="M130 98H370V157H130Z" fill="#734b9c"/><path d="M185 80V119M315 80V119" stroke="#4a2a64" stroke-width="8"/>${Array.from({length:9},(_,i)=>`<rect x="${163+i%3*65}" y="${188+Math.floor(i/3)*49}" width="30" height="22" fill="${i===4?'#ef873e':'#cfbadf'}"/>`).join('')}<circle class="calendar-check" cx="310" cy="300" r="45" fill="#734b9c"/><path d="M292 300L307 314L331 288" fill="none" stroke="#f6f3ee" stroke-width="3"/></g>`}
else if(tone==='intelligence'){shapes=`<g class="glyph-intelligence">${[0,1,2].map(i=>`<ellipse cx="250" cy="220" rx="145" ry="62" fill="none" stroke="${i===1?'#ef873e':'#9972b6'}" transform="rotate(${i*60} 250 220)"/>`).join('')}<circle cx="250" cy="220" r="42" fill="#734b9c"/><path d="M232 220H268M250 202V238" stroke="#e0cceb"/><circle class="intel-satellite" cx="391" cy="220" r="12" fill="#fdc234"/></g>`}
else{shapes=`<g class="glyph-platform">${Array.from({length:9},(_,i)=>`<rect x="${117+i%3*95}" y="${100+Math.floor(i/3)*95}" width="72" height="72" rx="${i===4?36:0}" fill="${i===4?'#ef873e':i%2?'#ccb4dc':'#734b9c'}" opacity="${i===4?1:.6+i%3*.15}"/>`).join('')}</g>`}return `<svg class="b-glyph bg-${tone}" viewBox="0 0 500 440" role="img" aria-label="Estudo visual de ${ce(cat)}"><g fill="none" stroke="#d0c0da" stroke-width=".6"><path d="M55 370H445M55 70H135M55 70V150M445 370V290"/></g>${shapes}<text x="55" y="405" font-size="9" letter-spacing="2" font-family="monospace" fill="#9c84ad">CATALISA / ${ce(cat).toUpperCase()}</text></svg>`}
function aStructure(){return `<svg class="a-structure" viewBox="0 0 1000 650" role="img" aria-label="Uma base comum sustenta composições para produtos diferentes"><defs><linearGradient id="a-surface"><stop stop-color="#c9b4d9"/><stop offset="1" stop-color="#734b9c"/></linearGradient></defs><path d="M100 430L500 200L905 432L505 663Z" fill="#ddd0e6" opacity=".3"/><g class="structure-base"><path d="M140 390L500 182L860 390L500 598Z" fill="#d7c6e2"/><path d="M140 390V421L500 630V598Z" fill="#ab8ac3"/><path d="M500 598L860 390V421L500 630Z" fill="#734b9c"/>${Array.from({length:4},(_,i)=>`<path d="M${212+i*72} ${348-i*42}L${572+i*72} ${556-i*42}M${212+i*72} ${432+i*42}L${572+i*72} ${224+i*42}" stroke="#b397c8" fill="none" stroke-width=".7"/>`).join('')}</g><g class="structure-branch sb-1"><path d="M300 272V157L410 92" stroke="#a78bbb" fill="none"/><path d="M240 132L325 83L411 132L326 181Z" fill="#d9cae4"/><path d="M240 132V201L326 251V181Z" fill="#9572b0"/><path d="M326 181L411 132V201L326 251Z" fill="#5a3677"/></g><g class="structure-branch sb-2"><path d="M500 390V130" stroke="#ae94c2" fill="none"/><path d="M429 94L514 45L600 94L515 143Z" fill="url(#a-surface)"/><path d="M429 94V210L515 260V143Z" fill="#734b9c"/><path d="M515 143L600 94V210L515 260Z" fill="#4c2968"/></g><g class="structure-branch sb-3"><path d="M700 270V157L640 123" stroke="#ad91bf" fill="none"/><path d="M625 174L710 125L796 174L711 223Z" fill="#ffad60"/><path d="M625 174V250L711 300V223Z" fill="#ec863e"/><path d="M711 223L796 174V250L711 300Z" fill="#ce6027"/></g><path class="structure-connection" d="M302 367L500 482L710 361" stroke="#734b9c" stroke-width="2" fill="none" stroke-dasharray="3 8"/><g fill="#734b9c"><circle cx="302" cy="367" r="5"/><circle cx="500" cy="482" r="5"/><circle cx="710" cy="361" r="5"/></g></svg>`}
const A_SCENARIOS=[{label:'Saúde',slug:'med',title:'Do primeiro contato ao encontro.',text:'Canal, agenda e vídeo participam do atendimento. O contexto clínico e a liberação do registro permanecem com o profissional.',blocks:['wpp-business','calendar','rooms','ai-engine'],steps:['Conversa','Disponibilidade','Encontro','Rascunho']},{label:'Recrutamento',slug:'recrutamento',title:'A seleção encontra suas ferramentas.',text:'Conversa, agenda e vídeo aparecem em uma jornada própria de recrutamento. O parecer depende de aprovação humana.',blocks:['wpp-business','calendar','rooms','ai-engine'],steps:['Contato','Agenda','Entrevista','Parecer']},{label:'Crédito',slug:'credit',title:'Uma jornada com etapas próprias.',text:'Política, cálculo, assinatura e registros participam do contexto de crédito. Cada capacidade mantém seu contrato.',blocks:['decision-engine','calculations-engine','e-signature','data-store'],steps:['Proposta','Política','Formalização','Operação']},{label:'Banking',slug:'banking',title:'Vários canais. Uma operação conectada.',text:'Aplicativo, desktop e console têm papéis distintos e se conectam às capacidades de identidade, conta e operação.',blocks:['iam','baas','api-keys','feature-flags'],steps:['Acesso','Conta','Autorização','Operação']}];
function aScenario(i,blocks){const s=A_SCENARIOS[i];return `<div class="a-scenario-art" data-vertical="${i}">${bGlyph(i<2?'Comunicação':i===2?'Decisão':'Financeiro','scenario')}</div><div class="a-scenario-copy"><span class="label">Composição / ${s.label}</span><h3>${s.title}</h3><p>${s.text}</p><ol>${s.steps.map(n=>`<li>${n}</li>`).join('')}</ol><div class="a-block-links">${s.blocks.map(slug=>{const b=blocks.find(b=>b.slug===slug);return ca('/capacidades/'+slug+'/',b?.name||slug)}).join('')}</div>${ca('/ecossistema/'+s.slug+'/','Veja o produto')}</div>`}
function aArchitecture(blocks){return `<div class="architecture-page"><section class="architecture-opening"><div class="wrap"><div>${cl('Arquitetura / Uma base para evoluir')}<h1>Produtos complexos.<br>Uma base<br>que continua.</h1><p>Novos contextos de negócio.<br>Capacidades que você pode recombinar.</p><a class="text-link" href="#reuso">Explore a composição <span>↓</span></a></div><div class="architecture-canopy">${aStructure()}</div><button class="visual-pause" data-visual-pause aria-pressed="false">Ⅱ Pausar movimento</button></div></section><section class="a-statement wrap"><span class="label">O diferencial está nas conexões</span><h2>Construir o próximo produto<br>sem reconstruir toda a base.</h2><div><p>Identidade, documentos, canais, decisões e dados voltam a aparecer em operações diferentes. Quando essas responsabilidades já têm forma e contrato, a equipe pode concentrar o trabalho no que muda: a experiência e as regras do novo contexto.</p><p>O reuso acontece na capacidade. A identidade do produto continua no domínio que ele atende.</p></div></section><section class="a-reuse" id="reuso"><div class="wrap"><div class="a-section-heading"><div>${cl('Uma base / Outros contextos')}<h2>Veja o que muda.<br>E o que encontra reuso.</h2></div><p>Explore jornadas de produtos<br>construídos sobre a plataforma.</p></div><div class="a-vertical-tabs" role="tablist" aria-label="Verticais de composição">${A_SCENARIOS.map((s,i)=>`<button role="tab" aria-selected="${i===0}" data-vertical-tab="${i}">${s.label}</button>`).join('')}</div><div class="a-scenario" id="a-scenario" role="tabpanel" aria-live="polite">${aScenario(0,blocks)}</div><p class="a-note">Leitura conceitual das responsabilidades. Não representa um diagrama de implementação interna ou uma execução real.</p></div></section><section class="a-efficiency wrap"><div>${cl('Eficiência por composição')}<h2>Menos trabalho<br>repetido.<br>Mais contexto.</h2></div><div class="a-principles"><article><span>01</span><h3>A responsabilidade já está delimitada.</h3><p>A equipe encontra uma capacidade com propósito e operações documentados, em vez de começar cada função comum como um projeto novo.</p></article><article><span>02</span><h3>A composição encontra o domínio.</h3><p>A jornada define como as peças se relacionam. Consulta, entrevista e crédito mantêm experiências e decisões próprias.</p></article><article><span>03</span><h3>A evolução tem uma fronteira.</h3><p>Uma política, um canal ou uma configuração pode ser discutido no escopo da capacidade responsável. O contrato torna essa mudança mais legível.</p></article></div></section><section class="a-contract-exhibit"><div class="wrap"><div class="contract-drawing"><svg viewBox="0 0 640 420" role="img" aria-label="Dois módulos se conectam por uma fronteira explícita"><path d="M80 235L250 137L390 218L220 316Z" fill="#c7afda"/><path d="M80 235V270L220 351V316Z" fill="#9270ad"/><path d="M220 316L390 218V253L220 351Z" fill="#5d3878"/><g class="contract-neighbor"><path d="M320 150L480 58L580 116L420 208Z" fill="#ede4f2"/><path d="M320 150V185L420 243V208Z" fill="#aa8ac1"/><path d="M420 208L580 116V151L420 243Z" fill="#734b9c"/></g><path d="M250 135L440 245" stroke="#ef873e" stroke-width="5"/><path class="contract-current" d="M100 395L540 140" stroke="#d7c4e4" stroke-width="1" stroke-dasharray="3 8" fill="none"/></svg></div><div>${cl('Conectar sem misturar')}<h2>A esteira busca.<br>O motor decide.</h2><p>Decision Platform organiza as fontes e o percurso. Decision Engine avalia a política publicada. As duas capacidades participam da mesma jornada, com responsabilidades distintas.</p><div>${ca('/capacidades/decision-platform/','A esteira')}${ca('/capacidades/decision-engine/','O motor')}</div></div></div></section><section class="a-layers wrap"><div><span class="label">Uma linguagem comum</span><h2>As partes precisam<br>se entender.</h2><p>Identidade, escopo e contratos ajudam a conectar capacidades. O estágio e os limites precisam ser conhecidos antes da adoção.</p></div><div>${[['Identidade','Usuário, organização e permissões acompanham o contexto da interação.','iam'],['Contratos','Cada capacidade explica o problema que resolve e as operações que oferece.',null],['Evidências','Versões e registros ajudam a compreender o que orientou uma ação.','audit-trail'],['Maturidade','Produção, Beta e Alpha representam estágios diferentes. Consulte cada capacidade.',null]].map(([n,t,s],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${n}<i aria-hidden="true">＋</i></summary><div><p>${t}</p>${ca(s?'/capacidades/'+s+'/':'/capacidades/','Explore a base')}</div></details>`).join('')}</div></section><section class="a-final"><div class="wrap"><span class="label">A biblioteca por trás da composição</span><h2>Encontre a peça.<br>Imagine o conjunto.</h2>${ca('/capacidades/','Explore os building blocks')}<span aria-hidden="true">↗</span></div></section></div>`}

function bLibraryArt(){return `<svg class="b-library-art" viewBox="0 0 850 650" role="img" aria-label="Peças de formas diferentes se organizam numa biblioteca de capacidades"><defs><linearGradient id="library-shade"><stop stop-color="#d1bfe0"/><stop offset="1" stop-color="#8c63aa"/></linearGradient></defs><g fill="none" stroke="#c5b0d3" stroke-width=".7"><path d="M80 440L430 230L780 430L430 635Z"/><path d="M180 500L530 290M280 560L630 350M180 380L530 580M280 320L630 520" stroke-dasharray="3 7"/></g><g class="library-tile lt-1"><path d="M100 282L250 195L390 276L240 363Z" fill="#e3d5ec"/><path d="M100 282V315L240 396V363Z" fill="#ab8bc1"/><path d="M240 363L390 276V309L240 396Z" fill="#704a8e"/><ellipse cx="246" cy="279" rx="62" ry="35" fill="#8e68aa"/><ellipse cx="246" cy="270" rx="62" ry="35" fill="#f6f3ee"/></g><g class="library-tile lt-2"><path d="M325 167L475 80L615 161L465 248Z" fill="url(#library-shade)"/><path d="M325 167V210L465 291V248Z" fill="#734b9c"/><path d="M465 248L615 161V204L465 291Z" fill="#4c2c66"/><path d="M379 169L474 114L560 164L465 219Z" fill="#d3c1e1"/><path d="M405 171L475 130L535 165L465 206Z" fill="#8b65a5"/></g><g class="library-tile lt-3"><path d="M485 372L635 285L775 366L625 453Z" fill="#f4eadf"/><path d="M485 372V402L625 483V453Z" fill="#d4c2d9"/><path d="M625 453L775 366V396L625 483Z" fill="#ae91be"/><path d="M540 373L636 318L722 368L626 423Z" fill="#d5c4df"/><path d="M566 373L637 332L697 367L626 408Z" fill="#f6f3ee"/></g><g class="library-tile lt-4"><path d="M255 463L405 376L545 457L395 544Z" fill="#ffad65"/><path d="M255 463V496L395 577V544Z" fill="#e48b46"/><path d="M395 544L545 457V490L395 577Z" fill="#be602e"/><path d="M310 461L405 407L491 457L396 512Z" fill="#e38640"/><path d="M333 458L406 416L469 452L396 494Z" fill="#f6f3ee"/></g><path class="library-connector" d="M246 275L475 148L630 365L398 464L246 275" fill="none" stroke="#9777ad" stroke-width="1.2" stroke-dasharray="3 8"/><g fill="#734b9c"><circle cx="246" cy="275" r="4"/><circle cx="475" cy="148" r="4"/><circle cx="630" cy="365" r="4"/></g><circle cx="398" cy="464" r="4" fill="#f4c138"/><text x="80" y="620" font-size="9" font-family="monospace" letter-spacing="2" fill="#ad96b9">INDEPENDÊNCIA / RECOMBINAÇÃO</text></svg>`}

function bAtlas(blocks){const cats=Object.keys(B_DOMAINS);return `<div class="b-atlas"><svg class="b-atlas-lines" viewBox="0 0 1100 550" aria-hidden="true"><g stroke="#a78ab9" stroke-width=".8" fill="none">${cats.map((cat,i)=>{const x=140+i%5*205,y=130+Math.floor(i/5)*280;return `<path d="M550 275Q${x} 275 ${x} ${y}"/>`}).join('')}</g><circle cx="550" cy="275" r="18" fill="#ef873e"/></svg>${cats.map((cat,i)=>`<button class="atlas-domain" data-domain-pick="${cat}" style="--atlas-x:${i%5};--atlas-y:${Math.floor(i/5)}"><span class="atlas-symbol as-${i}" aria-hidden="true">${bGlyph(cat,'atlas-'+i).replace('role="img"','aria-hidden="true"')}</span><strong>${cat}</strong><small>${blocks.filter(b=>b.category===cat).length} capacidades</small></button>`).join('')}</div>`}
function bCatalogRow(b){return `<a class="b-catalog-row" href="/capacidades/${b.slug}/" data-bb-row data-domain="${ce(b.category)}" data-stage="${ce(b.status)}" data-query="${ce((b.name+' '+b.tagline+' '+b.category).toLocaleLowerCase('pt-BR'))}"><span class="b-row-domain">${ce(b.category)}</span><span class="b-card-art" aria-hidden="true">${bGlyph(b.category,'catalog-'+b.slug)}</span><h3>${ce(b.name)}</h3><p>${ce(b.tagline)}</p><span class="b-row-stage ${b.status==='Produção'?'production':''}">${b.status}</span><span class="b-row-arrow" aria-hidden="true">↗</span></a>`}
function bCatalog(blocks){return `<div class="building-blocks-page"><section class="b-catalog-opening wrap"><div>${cl('Building blocks / Biblioteca de capacidades')}<h1>Peças com propósito.<br>Possibilidades<br>em conjunto.</h1><p>Identidade, dados, canais, decisão e operação.<br>Encontre a responsabilidade de que seu produto precisa.</p><a class="text-link" href="#biblioteca">Explore a biblioteca <span>↓</span></a></div><div class="catalog-cover">${bLibraryArt()}</div><button class="visual-pause" data-visual-pause aria-pressed="false">Ⅱ Pausar movimento</button></section><section class="b-domains-section"><div class="wrap"><div class="b-domains-title"><h2>Escolha pelo trabalho.</h2><p>Explore um domínio para encontrar as capacidades.</p></div>${bAtlas(blocks)}</div></section><section class="b-library wrap" id="biblioteca"><div class="b-library-title"><div>${cl('A biblioteca')}<h2>Encontre sua próxima peça.</h2></div><p>Contratos e estágios próprios.<br>Uma leitura clara antes de conectar.</p></div><div class="b-catalog-controls"><label><span class="sr-only">Buscar building block</span><input type="search" id="bb-search" placeholder="Busque pelo nome, domínio ou problema…"></label><select id="bb-domain" aria-label="Domínio do building block"><option value="">Todos os domínios</option>${Object.keys(B_DOMAINS).map(cat=>`<option>${cat}</option>`).join('')}</select><select id="bb-stage" aria-label="Estágio do building block"><option value="">Todos os estágios</option>${[...new Set(blocks.map(b=>b.status))].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="b-catalog-count"><span id="bb-result-count" role="status">${blocks.length} capacidades na biblioteca</span><button id="bb-clear">Limpar filtros</button></div><div class="b-catalog-results">${blocks.map(bCatalogRow).join('')}</div><p id="bb-empty" hidden>Nenhuma capacidade encontrada. Tente outro termo ou limpe os filtros.</p><button class="b-load-more" id="bb-more">Ver mais capacidades <span>＋</span></button><p class="b-source-note">Conteúdo editorial baseado na documentação pública. Consulte os contratos e estágios atualizados antes de integrar.</p>${ca('https://docs.catalisa.app/','Documentação completa')}</section><section class="b-reuse-banner"><div class="wrap"><h2>Uma peça pode participar<br>de mais de um produto.</h2><p>O contexto dá identidade à jornada.<br>A capacidade mantém sua responsabilidade.</p>${ca('/arquitetura/','Explore a arquitetura')}</div></section></div>`}
function bOverview(b){const summary=b.sections.find(s=>s.id==='resumo-executivo')||b.sections[0];if(!summary)return `<p>${ce(b.tagline)}</p>`;const pars=[...summary.html.matchAll(/<p\b[^>]*>[\s\S]*?<\/p>/g)].map(m=>m[0]);return pars.slice(0,2).join('')||`<p>${ce(b.tagline)}</p>`}
function bJourney(b){const d=bDomain(b.category);return `<div class="b-journey-drawing"><svg viewBox="0 0 1000 250" role="img" aria-label="${ce(d.input)} se conecta a ${ce(b.name)}, que participa de ${ce(d.output)}"><path d="M90 125H910" stroke="#c4b2d1" fill="none"/><path class="block-journey-path" d="M90 125H910" stroke="#734b9c" stroke-width="2" fill="none"/><circle cx="100" cy="125" r="27" fill="#f6f3ee" stroke="#a688ba"/><path d="M480 70L567 120L480 170L393 120Z" fill="#734b9c"/><path d="M480 90L532 120L480 150L428 120Z" fill="none" stroke="#cdb7de"/><circle cx="900" cy="125" r="27" fill="#ef873e"/><circle cx="100" cy="125" r="7" fill="#9e7cb7"/></svg><div><span>${d.input}</span><strong>${ce(b.name)}</strong><span>${d.output}</span></div></div>`}
function bDetail(b,blocks){const d=bDomain(b.category),related=C_PRODUCTS.filter(p=>p.blocks?.includes(b.slug)),siblings=blocks.filter(x=>x.category===b.category&&x.slug!==b.slug).slice(0,3);return `<article class="building-detail bd-${d.tone}"><nav class="wrap breadcrumb" aria-label="Localização"><a href="/capacidades/">Building blocks</a><span>/</span>${b.category}</nav><header class="b-detail-heading wrap"><div>${cl(b.category+' / Building block')}<h1>${ce(b.name)}</h1><p>${ce(b.tagline)}</p><div class="b-detail-meta"><span class="b-row-stage ${b.status==='Produção'?'production':''}">${b.status}</span>${ca(b.source,'Referência oficial')}</div></div><div class="b-detail-art">${bGlyph(b.category,'detail-'+b.slug)}</div><button class="visual-pause" data-visual-pause aria-pressed="false">Ⅱ Pausar movimento</button></header><nav class="b-detail-nav wrap" aria-label="Explore esta capacidade"><a href="#papel">O papel</a><a href="#composicao">Na composição</a><a href="#aprofundar">Aprofundar</a></nav><section class="b-role wrap" id="papel"><div><span class="label">O papel da capacidade</span><h2>${d.title}</h2><p>${d.copy}</p></div><div class="b-overview">${bOverview(b)}</div></section><section class="b-journey-section" id="composicao"><div class="wrap"><span class="label">Uma leitura da composição</span><h2>Uma responsabilidade.<br>Parte de uma jornada.</h2>${bJourney(b)}<p class="a-note">Visualização conceitual do papel da capacidade; não é um contrato de entrada e saída de API.</p></div></section>${related.length?`<section class="b-product-context wrap"><div><span class="label">Capacidade em contexto</span><h2>Onde essa peça<br>encontra uma expressão.</h2><p>Seleção de produtos relacionados às responsabilidades desta capacidade.</p></div><div>${related.map(p=>`<a href="/ecossistema/${p.slug}/"><span>${p.category}</span><h3>${p.name}</h3><p>${p.principle||p.title}</p><i aria-hidden="true">↗</i></a>`).join('')}</div></section>`:''}<section class="b-deep wrap" id="aprofundar"><div class="b-deep-heading"><span class="label">Aprofundar a capacidade</span><h2>Conheça o escopo.<br>Confira os limites.</h2><p>Abra o que deseja explorar.<br>A referência completa continua na documentação.</p>${ca(b.source,'Contrato e documentação')}</div><div class="b-doc-panels">${b.sections.filter(s=>s.id!=='resumo-executivo').map(s=>`<details ${/limites/i.test(s.id)?'open':''}><summary>${s.title}<span aria-hidden="true">＋</span></summary><div class="b-doc-content">${s.html}</div></details>`).join('')}${b.status!=='Produção'?`<aside class="b-stage-context"><strong>${b.status} é parte do contexto.</strong><p>Confira escopo, maturidade e limites na documentação oficial antes de adotar esta capacidade.</p></aside>`:''}</div></section>${siblings.length?`<section class="b-siblings wrap"><span class="label">Continue neste domínio</span><div>${siblings.map(x=>`<a href="/capacidades/${x.slug}/"><h3>${x.name}</h3><p>${x.tagline}</p><span>Explore a capacidade ↗</span></a>`).join('')}</div></section>`:''}</article>`}
const bOriginalPage=cPage;
cPage=function(route,blocks){if(route==='/capacidades/')return bCatalog(blocks);return bOriginalPage(route,blocks)};
cBlock=bDetail;
function bBind(){const root=document.querySelector('.architecture-page,.building-blocks-page,.building-detail');if(!root)return;const q=document.getElementById('bb-search');if(q){let limit=12;const domain=document.getElementById('bb-domain'),stage=document.getElementById('bb-stage'),rows=[...document.querySelectorAll('[data-bb-row]')];const filter=()=>{const term=q.value.trim().toLocaleLowerCase('pt-BR');const matches=rows.filter(row=>row.dataset.query.includes(term)&&(!domain.value||domain.value===row.dataset.domain)&&(!stage.value||stage.value===row.dataset.stage));rows.forEach(row=>row.hidden=true);matches.slice(0,limit).forEach(row=>row.hidden=false);document.getElementById('bb-result-count').textContent=matches.length+' capacidades encontradas'+(matches.length>limit?' · mostrando '+limit:'');document.getElementById('bb-empty').hidden=matches.length>0;document.getElementById('bb-more').hidden=matches.length<=limit;document.getElementById('bb-clear').hidden=!term&&!domain.value&&!stage.value;document.querySelectorAll('[data-domain-pick]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.domainPick===domain.value)))};q.addEventListener('input',()=>{limit=12;filter()});[domain,stage].forEach(el=>el.addEventListener('change',()=>{limit=12;filter()}));document.getElementById('bb-clear').addEventListener('click',()=>{q.value='';domain.value='';stage.value='';limit=12;filter()});document.getElementById('bb-more').addEventListener('click',()=>{limit+=12;filter()});document.querySelectorAll('[data-domain-pick]').forEach(b=>b.addEventListener('click',()=>{domain.value=b.dataset.domainPick;limit=12;filter();document.getElementById('biblioteca').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})}));filter()}
document.querySelectorAll('[data-visual-pause]').forEach(b=>b.addEventListener('click',()=>{const paused=root.classList.toggle('visuals-paused');b.setAttribute('aria-pressed',String(paused));b.textContent=paused?'▶ Retomar movimento':'Ⅱ Pausar movimento'}));const tabs=[...document.querySelectorAll('[data-vertical-tab]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.getElementById('a-scenario').innerHTML=aScenario(i,window.CATALISA_BLOCKS||[])});b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click()}})});if(tabs.length)fetch('/assets/blocks.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>window.CATALISA_BLOCKS=data).catch(()=>{document.getElementById('a-scenario').insertAdjacentHTML('beforeend','<p class="a-note">Consulte os links do catálogo para aprofundar as capacidades.</p>')})}
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('DOMContentLoaded',bBind);

/* Business readings of documented use scenarios. No client outcomes are implied. */
const B_STORIES={"ai-engine": {"headline": "Transforme conversas em informação útil.", "intro": "Organize mensagens, resuma textos e interprete documentos para apoiar as equipes no trabalho diário.", "caseTitle": "Atendimento que encontra a fila certa", "problem": "Uma financeira recebe dúvidas, reclamações e pedidos de negociação no mesmo canal. Separar tudo por palavras-chave faz conversas importantes chegarem à equipe errada.", "action": "A inteligência artificial identifica o assunto e o tom da mensagem. A operação usa essa leitura para encaminhar o atendimento e definir prioridades.", "value": "A equipe recebe conversas com mais contexto e concentra a atenção nos casos que precisam dela.", "limit": "Classificar uma mensagem não resolve o atendimento. Encaminhamento, respostas e revisão humana precisam fazer parte da jornada.", "source": "https://docs.catalisa.app/blocks/ai-engine/", "sourceSection": "casos-de-uso-reais"}, "analytics": {"headline": "Enxergue onde a jornada perde força.", "intro": "Acompanhe quantas pessoas avançam, desistem ou encontram uma barreira, sem transformar a análise de uso em um cadastro pessoal.", "caseTitle": "Entender o caminho até o primeiro Pix", "problem": "O time de produto precisa saber se uma transferência parou por abandono, recusa ou dificuldade na experiência.", "action": "O bloco organiza a contagem das etapas e dos desfechos previstos na jornada.", "value": "A equipe ganha uma leitura do funil para investigar atritos e orientar melhorias.", "limit": "O bloco está em Alpha. A leitura depende dos eventos que cada produto já envia; jornadas ainda não conectadas não aparecem como concluídas.", "source": "https://docs.catalisa.app/blocks/analytics/", "sourceSection": "casos-de-uso-reais"}, "api-keys": {"headline": "Dê a cada parceiro o acesso de que precisa.", "intro": "Conecte sistemas externos com permissões e limites próprios, que podem ser revogados quando a relação muda.", "caseTitle": "Um marketplace acompanha pedidos com acesso restrito", "problem": "Três parceiros precisam consultar pedidos. Um acesso compartilhado e amplo deixa ações que eles não deveriam executar ao alcance de todos.", "action": "Cada parceiro recebe seu próprio acesso, limitado às consultas acordadas e ao período do contrato.", "value": "A operação consegue acompanhar e encerrar cada integração separadamente.", "limit": "O escopo precisa refletir o contrato de cada parceiro. O bloco organiza o acesso; não substitui a definição dessas responsabilidades.", "source": "https://docs.catalisa.app/blocks/api-keys/", "sourceSection": "casos-de-uso-reais"}, "audit-trail": {"headline": "Dê contexto a cada mudança importante.", "intro": "Consulte quem alterou uma informação, quando isso aconteceu e o que mudou, dentro da organização.", "caseTitle": "Descobrir por que uma taxa mudou", "problem": "Uma condição comercial aparece diferente da aprovada. A equipe precisa reconstruir o que aconteceu.", "action": "As alterações registradas pelos blocos ficam reunidas em um histórico consultável, com autoria e momento da mudança.", "value": "A investigação começa por uma linha do tempo, em vez de depender da memória de quem participou.", "limit": "Em Beta. A cobertura depende das ações que enviam registros à trilha e do prazo de retenção configurado.", "source": "https://docs.catalisa.app/blocks/audit-trail/", "sourceSection": "casos-de-uso-reais"}, "baas": {"headline": "Leve serviços bancários à jornada do seu produto.", "intro": "Conecte abertura de contas, consultas e movimentações a um parceiro bancário, dentro da experiência da sua empresa.", "caseTitle": "Separar os recursos de cada operação", "problem": "Uma financeira precisa acompanhar o dinheiro de operações diferentes sem reconstruir essa separação em planilhas.", "action": "A jornada associa contas e movimentações à operação correspondente, usando os serviços do parceiro bancário.", "value": "O time passa a consultar o movimento de cada operação com uma referência comum.", "limit": "Em Beta. A execução bancária depende do provedor contratado e das homologações necessárias; a Catalisa fornece a camada de software.", "source": "https://docs.catalisa.app/blocks/baas/", "sourceSection": "casos-de-uso-reais"}, "banking": {"headline": "Uma jornada bancária com começo, contexto e continuidade.", "intro": "Conecte o aplicativo às capacidades que cuidam de identidade, conta e movimentação, respeitando as regras de cada etapa.", "caseTitle": "Confirmar uma transferência sem reenviar o pagamento", "problem": "O cliente envia um Pix, mas perde a conexão antes de receber a confirmação. Repetir a operação pode gerar dúvida e insegurança.", "action": "A jornada consulta o desfecho da tentativa anterior e orienta o próximo passo antes de iniciar outra operação.", "value": "O aplicativo consegue comunicar o que está confirmado e o que ainda precisa ser verificado.", "limit": "Em Alpha, com cobertura parcial da jornada. Serviços de conta e dinheiro ficam nas capacidades bancárias; consulte as funções disponíveis.", "source": "https://docs.catalisa.app/blocks/banking/", "sourceSection": "casos-de-uso-reais"}, "banking-product-portfolio": {"headline": "Evolua a oferta sem apagar o que foi contratado.", "intro": "Organize produtos financeiros e suas versões para que mudanças comerciais respeitem as condições já assumidas.", "caseTitle": "Uma nova condição para os próximos contratos", "problem": "Uma mudança de imposto ou condição entra em vigor. Contratos anteriores precisam manter a referência do que foi acordado.", "action": "A oferta evolui em uma nova versão, enquanto cada contratação continua ligada à sua referência.", "value": "A operação distingue o produto oferecido hoje das condições de uma contratação passada.", "limit": "Em Beta. Regras, aprovações e condições precisam ser configuradas e validadas para cada operação.", "source": "https://docs.catalisa.app/blocks/banking-product-portfolio/", "sourceSection": "casos-de-uso-reais"}, "billing": {"headline": "Transforme uso em cobrança acompanhável.", "intro": "Organize assinaturas, consumo e faturas para modelos em que o preço depende do serviço utilizado.", "caseTitle": "Cobrar pelas consultas realizadas", "problem": "Uma empresa cobra por consulta de crédito e fecha o mês cruzando planilhas para descobrir o consumo de cada cliente.", "action": "O consumo registrado alimenta as regras de cobrança e a composição das faturas.", "value": "A equipe consegue acompanhar a origem da cobrança com mais clareza.", "limit": "Em Beta. Medição, preços e ciclo de faturamento precisam estar alinhados ao contrato comercial.", "source": "https://docs.catalisa.app/blocks/billing/", "sourceSection": "casos-de-uso-reais"}, "biometrics": {"headline": "Confirme a presença de quem está do outro lado.", "intro": "Combine prova de vida e comparação facial na abertura de conta ou na confirmação de uma operação.", "caseTitle": "Uma selfie na abertura de conta", "problem": "Uma jornada digital precisa avaliar se há uma pessoa presente e se ela corresponde à identidade apresentada.", "action": "O cliente passa pela captura orientada; a jornada recebe a avaliação e as evidências disponíveis.", "value": "A equipe incorpora a verificação à jornada e consegue consultar o fundamento da avaliação.", "limit": "Em Alpha. O motor próprio não tem certificação independente de laboratório; provedores declarados dependem de integração e credenciais.", "source": "https://docs.catalisa.app/blocks/biometrics/", "sourceSection": "casos-de-uso-reais"}, "bureaus": {"headline": "Consulte melhor. Evite pagar pela mesma pergunta.", "intro": "Reúna consultas cadastrais e seu histórico para apoiar análises e acompanhar a finalidade de cada pesquisa.", "caseTitle": "O mesmo cliente aparece em três etapas", "problem": "Uma proposta passa por pré-análise, decisão e formalização. As três etapas podem repetir a mesma consulta paga.", "action": "Quando a informação ainda está válida, o bloco reaproveita a consulta já realizada.", "value": "A operação pode reduzir consultas repetidas e acompanhar quem pesquisou, quando e por qual finalidade.", "limit": "O reaproveitamento depende da validade e das condições da consulta. Fornecedores disponíveis e bases autorizadas devem ser conferidos na documentação.", "source": "https://docs.catalisa.app/blocks/bureaus/", "sourceSection": "casos-de-uso-reais"}, "calculations-engine": {"headline": "Uma conta coerente do começo ao contrato.", "intro": "Calcule parcelas, amortização e encargos com uma referência comum para simulação e formalização.", "caseTitle": "A parcela mostrada precisa ser a contratada", "problem": "O aplicativo apresenta uma parcela e o contrato calcula outra, porque cada etapa usa sua própria conta.", "action": "As etapas consultam a mesma capacidade de cálculo, com os parâmetros da operação.", "value": "Simulação e formalização passam a compartilhar o mesmo fundamento de cálculo.", "limit": "Métodos, encargos e parâmetros precisam ser validados para cada modalidade financeira.", "source": "https://docs.catalisa.app/blocks/calculations-engine/", "sourceSection": "casos-de-uso-reais"}, "calendar": {"headline": "Ofereça horários que cabem na agenda real.", "intro": "Conecte disponibilidade e agendamento às agendas que os profissionais já usam.", "caseTitle": "Agendar com o analista sem uma agenda paralela", "problem": "O cliente escolhe um horário, mas a agenda interna da plataforma não acompanha os compromissos do profissional.", "action": "A jornada consulta a disponibilidade das agendas conectadas para oferecer e organizar o encontro.", "value": "O agendamento encontra espaço na rotina do profissional e na experiência do cliente.", "limit": "Em Beta. O acesso depende da autorização do usuário e das agendas conectadas.", "source": "https://docs.catalisa.app/blocks/calendar/", "sourceSection": "casos-de-uso-reais"}, "cms": {"headline": "Atualize a experiência no ritmo do negócio.", "intro": "Organize textos, marca, avisos e campanhas do aplicativo sem depender de uma nova versão para cada mudança de conteúdo.", "caseTitle": "A promoção termina junto com a campanha", "problem": "Uma oferta acaba no domingo, mas continua aparecendo no aplicativo até a próxima atualização.", "action": "A equipe define o período de exibição e publica o conteúdo nos espaços previstos pelo produto.", "value": "A comunicação pode acompanhar o calendário comercial com mais precisão.", "limit": "Em Alpha. O conteúdo usa formatos e ações previstos pelo aplicativo; novas funções continuam exigindo evolução do produto.", "source": "https://docs.catalisa.app/blocks/cms/", "sourceSection": "casos-de-uso-reais"}, "commerce": {"headline": "Conecte a venda ao que a operação consegue entregar.", "intro": "Reúna catálogo, estoque e pedidos para dar continuidade à experiência de compra.", "caseTitle": "Várias lojas, uma leitura do estoque", "problem": "Uma rede vende o mesmo item em canais diferentes e descobre tarde que a unidade disponível já foi comprometida.", "action": "A operação conecta a disponibilidade e os pedidos ao mesmo conjunto de informações comerciais.", "value": "Os canais passam a trabalhar com uma referência comum para vender e acompanhar o pedido.", "limit": "A qualidade da disponibilidade depende das lojas e integrações que atualizam o estoque.", "source": "https://docs.catalisa.app/blocks/commerce/", "sourceSection": "casos-de-uso-reais"}, "companies": {"headline": "Saiba quem pode representar a empresa.", "intro": "Reúna dados, documentos e poderes de representação para apoiar assinaturas e autorizações.", "caseTitle": "O termo chega a quem tem poder para assinar", "problem": "Uma operação com uma empresa precisa ir além de registrar que alguém aceitou: é necessário conhecer os poderes de representação.", "action": "A jornada consulta os documentos vigentes e as combinações de representantes previstas para aquela operação.", "value": "A preparação da assinatura passa a considerar quem pode representar a empresa naquele valor e momento.", "limit": "Em Alpha. A análise completa de beneficiários, revisões e integração com envelopes de assinatura ainda tem partes em evolução.", "source": "https://docs.catalisa.app/blocks/companies/", "sourceSection": "casos-de-uso-reais"}, "customers": {"headline": "Dê continuidade ao relacionamento com o cliente.", "intro": "Mantenha os dados de contato e cadastro em uma referência compartilhada pelas jornadas.", "caseTitle": "Um cliente, três telefones diferentes", "problem": "Atendimento, proposta e cobrança guardam cadastros separados e deixam a equipe sem saber qual informação usar.", "action": "As jornadas consultam e atualizam a mesma referência de cliente.", "value": "A operação reduz desencontros e consegue continuar o relacionamento com mais contexto.", "limit": "Cadastro depende da qualidade das informações e das regras de atualização adotadas pela empresa.", "source": "https://docs.catalisa.app/blocks/customers/", "sourceSection": "casos-de-uso-reais"}, "data-extraction": {"headline": "Tire a redigitação do caminho.", "intro": "Transforme informações de documentos em campos que a equipe pode conferir e usar na jornada.", "caseTitle": "O cadastro avança a partir do documento", "problem": "A abertura de conta fica parada enquanto alguém copia informações de documentos enviados pelo cliente.", "action": "O bloco identifica os dados e os apresenta de forma organizada para a próxima etapa.", "value": "A equipe pode se concentrar na conferência e nas exceções, em vez de copiar cada campo.", "limit": "A extração pode errar. Documentos, qualidade da imagem e campos relevantes precisam ser avaliados, com revisão onde necessário.", "source": "https://docs.catalisa.app/blocks/data-extraction/", "sourceSection": "casos-de-uso-reais"}, "data-store": {"headline": "Guarde o contexto para a próxima etapa.", "intro": "Organize as informações de uma jornada para que cada participante encontre o estado atual do trabalho.", "caseTitle": "A proposta continua de onde parou", "problem": "Uma esteira precisa guardar dados, pendências e o andamento de cada proposta ao longo de várias etapas.", "action": "A jornada registra esse contexto em uma base organizada para consulta e atualização.", "value": "As etapas deixam de depender de informações dispersas para saber o próximo passo.", "limit": "O modelo das informações, os acessos e o tempo de guarda fazem parte da configuração da jornada.", "source": "https://docs.catalisa.app/blocks/data-store/", "sourceSection": "casos-de-uso-reais"}, "decision-engine": {"headline": "Mude a regra no ritmo da decisão de negócio.", "intro": "Organize políticas em tabelas que podem ser revisadas, publicadas e consultadas com histórico de versões.", "caseTitle": "A política de risco muda com o negócio", "problem": "O comitê decide ajustar um critério de crédito, mas a regra depende de uma alteração no aplicativo.", "action": "A equipe responsável revisa a tabela, publica a versão aprovada e passa a avaliar as propostas com essa referência.", "value": "O negócio ganha uma forma mais clara de governar a regra e identificar qual versão orientou cada avaliação.", "limit": "O bloco aplica regras definidas pela empresa. Buscar informações, organizar a esteira e decidir sobre revisões humanas são responsabilidades da jornada.", "source": "https://docs.catalisa.app/blocks/decision-engine/", "sourceSection": "casos-de-uso-reais"}, "decision-platform": {"headline": "Prepare o contexto antes de aplicar a política.", "intro": "Conecte as consultas e as etapas necessárias para reunir as informações de uma avaliação.", "caseTitle": "Uma proposta chega mais completa à decisão", "problem": "A análise de crédito depende de dados que estão em fontes diferentes e precisam chegar na ordem certa.", "action": "A esteira reúne e organiza essas informações e as encaminha à avaliação da política.", "value": "A operação consegue distinguir a preparação do dossiê da aplicação da regra.", "limit": "A cobertura depende das fontes conectadas. A avaliação das regras pertence ao Decision Engine; tarefas humanas precisam de uma jornada própria.", "source": "https://docs.catalisa.app/blocks/decision-platform/", "sourceSection": "casos-de-uso-reais"}, "document-template": {"headline": "Faça o documento acompanhar a operação.", "intro": "Organize modelos e preencha documentos com os dados da jornada, preservando uma referência do conteúdo usado.", "caseTitle": "Uma cláusula muda e o modelo acompanha", "problem": "A equipe jurídica altera uma cláusula, mas a formalização ainda depende de um modelo fixo no aplicativo.", "action": "O modelo é atualizado e usado para gerar os próximos documentos com as informações da operação.", "value": "O trabalho de ajustar o texto pode acompanhar o processo de revisão do negócio.", "limit": "A revisão jurídica, a aprovação do modelo e a qualidade dos dados continuam sendo responsabilidades da operação.", "source": "https://docs.catalisa.app/blocks/document-template/", "sourceSection": "casos-de-uso-reais"}, "e-signature": {"headline": "Conduza a assinatura até o documento concluído.", "intro": "Organize participantes, ordem de assinatura e acompanhamento dos documentos da operação.", "caseTitle": "Devedor e avalista assinam na sequência certa", "problem": "A formalização exige assinaturas de pessoas diferentes e a equipe precisa acompanhar quem ainda não concluiu.", "action": "A jornada prepara o documento, define os participantes e acompanha as etapas junto ao provedor de assinatura.", "value": "A equipe encontra o andamento da formalização em uma referência comum.", "limit": "A modalidade de assinatura e sua adequação ao documento devem ser definidas pela operação, com o provedor contratado.", "source": "https://docs.catalisa.app/blocks/e-signature/", "sourceSection": "casos-de-uso-reais"}, "email": {"headline": "Traga a conversa para perto da operação.", "intro": "Conecte mensagens de e-mail ao contexto em que o relacionamento acontece.", "caseTitle": "O CRM enxerga mais da negociação", "problem": "A negociação fica na caixa de entrada do vendedor e o restante da equipe só vê o que foi anotado manualmente.", "action": "Com a autorização de acesso, as mensagens relevantes entram no fluxo do produto e ajudam a compor o histórico.", "value": "A equipe pode continuar o atendimento com acesso ao contexto da conversa.", "limit": "A conexão depende da autorização do usuário, do provedor e das permissões concedidas.", "source": "https://docs.catalisa.app/blocks/email/", "sourceSection": "casos-de-uso-reais"}, "feature-flags": {"headline": "Apresente a mudança aos poucos.", "intro": "Controle a disponibilidade de funções por público para experimentar e ampliar o uso de forma gradual.", "caseTitle": "Uma mudança começa com poucos correspondentes", "problem": "A financeira quer experimentar uma nova condição com um grupo reduzido antes de disponibilizá-la à rede inteira.", "action": "A equipe define o público que recebe a mudança e ajusta a disponibilidade conforme a avaliação da operação.", "value": "A expansão pode acontecer por etapas, com possibilidade de interromper a exposição da função.", "limit": "Liberar uma função não substitui testar sua qualidade ou validar suas regras de negócio.", "source": "https://docs.catalisa.app/blocks/feature-flags/", "sourceSection": "casos-de-uso-reais"}, "file-storage": {"headline": "Dê um lugar aos documentos da jornada.", "intro": "Receba e organize arquivos para que as etapas autorizadas encontrem o material de que precisam.", "caseTitle": "Os documentos acompanham a proposta", "problem": "Uma proposta de crédito recebe vários anexos e a equipe precisa saber onde estão e a que operação pertencem.", "action": "A jornada envia os arquivos e mantém referências para recuperá-los com o acesso adequado.", "value": "O documento deixa de depender da pasta ou da caixa de mensagens de uma pessoa.", "limit": "Acesso, tempo de guarda e vínculo com a operação precisam ser definidos na jornada.", "source": "https://docs.catalisa.app/blocks/file-storage/", "sourceSection": "casos-de-uso-reais"}, "iam": {"headline": "Cada pessoa no contexto certo.", "intro": "Organize usuários, empresas e permissões para que cada participante tenha acesso ao trabalho que lhe cabe.", "caseTitle": "Correspondentes compartilham a plataforma, não os dados", "problem": "Uma financeira atende empresas parceiras diferentes e precisa delimitar a visão de cada equipe.", "action": "Usuários e permissões ficam associados à organização e aos papéis definidos para a operação.", "value": "O mesmo produto pode atender organizações diferentes com fronteiras de acesso explícitas.", "limit": "As permissões precisam ser desenhadas e revisadas conforme os papéis reais de cada empresa.", "source": "https://docs.catalisa.app/blocks/iam/", "sourceSection": "casos-de-uso-reais"}, "meta-account": {"headline": "Mantenha a relação com a Meta sob controle.", "intro": "Reúna a visão das contas, números e autorizações usados na operação de WhatsApp.", "caseTitle": "Trocar de fornecedor sem perder o controle da conta", "problem": "Uma rede descobre que a conta de WhatsApp pertence ao fornecedor e que a mudança de serviço depende dele.", "action": "A operação parte de uma conta da própria empresa, com acesso delegado ao prestador.", "value": "A empresa mantém a governança dos ativos e consegue revisar quem tem autorização para operá-los.", "limit": "Em Beta e pré-produção na documentação consultada. A disponibilidade precisa ser confirmada antes de planejar a operação.", "source": "https://docs.catalisa.app/blocks/meta-account/", "sourceSection": "casos-de-uso-reais"}, "open-finance": {"headline": "Analise dados que o cliente autorizou compartilhar.", "intro": "Traga informações bancárias para a jornada com o consentimento do cliente, por meio do provedor contratado.", "caseTitle": "Analisar renda sem pedir um extrato por e-mail", "problem": "A proposta para na etapa de anexar extratos, com arquivos incompletos e formatos diferentes.", "action": "O cliente autoriza o compartilhamento no fluxo do provedor e as informações bancárias passam a apoiar a análise.", "value": "A operação pode reduzir o trabalho de receber e conferir documentos enviados manualmente.", "limit": "A Catalisa fornece o software de integração. O acesso depende do consentimento e de um provedor agregador contratado e habilitado.", "source": "https://docs.catalisa.app/blocks/open-finance/", "sourceSection": "casos-de-uso-reais"}, "payments": {"headline": "Conecte a cobrança à jornada do cliente.", "intro": "Organize meios e acompanhamento de pagamento para que a operação saiba o que foi cobrado e recebido.", "caseTitle": "A parcela ganha a opção de pagamento por Pix", "problem": "Uma financeira quer ampliar as opções de cobrança sem tratar cada nova forma de pagamento como um produto separado.", "action": "A jornada prepara a cobrança e acompanha seu andamento por meio do provedor conectado.", "value": "A equipe reúne a visão do pagamento no contexto da operação.", "limit": "Meios disponíveis, liquidação e condições comerciais dependem dos provedores e contratos conectados.", "source": "https://docs.catalisa.app/blocks/payments/", "sourceSection": "casos-de-uso-reais"}, "people": {"headline": "Peça de novo apenas o que precisa ser atualizado.", "intro": "Reúna o que foi verificado sobre uma pessoa, a origem da informação e sua validade.", "caseTitle": "O cliente volta e o cadastro tem memória", "problem": "Um cedente retorna meses depois e o analista pede todos os documentos porque não sabe o que ainda está válido.", "action": "A jornada consulta o que já foi comprovado e identifica as informações que precisam de atualização.", "value": "O novo atendimento pode se concentrar no que falta, em vez de repetir toda a coleta.", "limit": "Em Alpha, ainda sem publicação operacional na documentação consultada. Consentimento formal e outras partes do ciclo continuam em evolução.", "source": "https://docs.catalisa.app/blocks/people/", "sourceSection": "casos-de-uso-reais"}, "pricing-engine": {"headline": "Dê uma lógica clara à condição comercial.", "intro": "Organize faixas de preço, taxas e componentes da oferta para que a jornada consulte uma referência comum.", "caseTitle": "A condição acompanha o custo da operação", "problem": "O custo de captação muda e a equipe precisa ajustar as condições oferecidas sem manter uma planilha diferente por canal.", "action": "Os responsáveis atualizam as faixas e regras comerciais usadas na composição da oferta.", "value": "A operação consegue relacionar o preço apresentado à regra comercial que o originou.", "limit": "Em Beta. Tipos de regra disponíveis e composição de taxas precisam ser conferidos; a ligação com decisões não cobre todas as modalidades declaradas.", "source": "https://docs.catalisa.app/blocks/pricing-engine/", "sourceSection": "casos-de-uso-reais"}, "products": {"headline": "Deixe a oferta acompanhar a decisão comercial.", "intro": "Organize limites, prazos e condições dos produtos de crédito usados pela sua operação.", "caseTitle": "O prazo da oferta muda sem reescrever a jornada", "problem": "O comercial quer ampliar o prazo máximo, mas essa condição está fixa dentro do aplicativo.", "action": "As condições ficam reunidas no cadastro do produto, consultado pela jornada ao preparar a oferta.", "value": "O time passa a administrar os parâmetros comerciais em uma referência própria.", "limit": "Para famílias, variantes e versões publicadas com governança mais ampla, avalie Banking Product Portfolio.", "source": "https://docs.catalisa.app/blocks/products/", "sourceSection": "casos-de-uso-reais"}, "rooms": {"headline": "Faça a conversa participar da jornada.", "intro": "Conecte encontros por vídeo ao atendimento e às informações que precisam continuar depois da reunião.", "caseTitle": "A entrevista de crédito ganha continuidade", "problem": "Analista e cliente conversam por vídeo, mas o combinado se perde antes de chegar ao restante da operação.", "action": "A jornada associa a sala e os registros autorizados ao atendimento e às próximas etapas.", "value": "A equipe consegue retomar o contexto e dar continuidade ao que foi tratado.", "limit": "Gravação, acesso e uso das informações precisam de autorização e regras de guarda; processamento posterior depende da composição com outras capacidades.", "source": "https://docs.catalisa.app/blocks/rooms/", "sourceSection": "casos-de-uso-reais"}, "service-attestations": {"headline": "Confirme o serviço na fonte de quem paga.", "intro": "Consulte a confirmação de serviços prestados e acompanhe alterações no repasse previsto.", "caseTitle": "Antecipação de um plantão confirmado", "problem": "Um fundo avalia antecipar o pagamento de um plantão. Um comprovante enviado pelo prestador não informa necessariamente mudanças ou cancelamentos posteriores.", "action": "A jornada consulta a fonte do pagador e usa a confirmação para compor a análise do repasse.", "value": "O processo pode trabalhar com uma referência da fonte e identificar alterações que afetam a operação.", "limit": "Em Alpha. A documentação informa uso de provedor simulado enquanto falta a credencial real; o cenário não representa operação de cliente comprovada.", "source": "https://docs.catalisa.app/blocks/service-attestations/", "sourceSection": "casos-de-uso-reais"}, "slack": {"headline": "Encontre a equipe no canal em que ela trabalha.", "intro": "Leve conversas e respostas do produto ao Slack, respeitando a autorização e os canais escolhidos.", "caseTitle": "O assistente chega ao Slack", "problem": "Um assistente já atende por outro canal, mas os clientes corporativos querem conversar com ele no ambiente de trabalho.", "action": "A empresa conecta o ambiente e seleciona as conversas que podem chegar ao produto.", "value": "A experiência ganha um novo ponto de contato sem criar outra rotina para o usuário.", "limit": "Em Alpha. Distribuição do aplicativo e partes do ciclo de conexão ainda dependem de evolução e aprovação do provedor.", "source": "https://docs.catalisa.app/blocks/slack/", "sourceSection": "casos-de-uso-reais"}, "sso": {"headline": "Entre com a identidade que a empresa já usa.", "intro": "Conecte o acesso à conta corporativa para simplificar a entrada na plataforma e respeitar o contexto de cada organização.", "caseTitle": "O correspondente usa a conta de trabalho", "problem": "Uma empresa parceira quer que seus operadores acessem a plataforma com a identidade corporativa, sem manter outra senha.", "action": "A organização habilita o provedor e os domínios permitidos para a entrada dos seus usuários.", "value": "O acesso passa a aproveitar a identidade que a empresa administra no dia a dia.", "limit": "Em Beta. A documentação aponta etapas pendentes no vínculo com o usuário interno; o ciclo completo precisa ser validado antes da adoção.", "source": "https://docs.catalisa.app/blocks/sso/", "sourceSection": "casos-de-uso-reais"}, "webhooks-engine": {"headline": "Faça o próximo sistema saber o que aconteceu.", "intro": "Entregue avisos de acontecimentos da plataforma, com acompanhamento e novas tentativas quando o destino não responde.", "caseTitle": "O contrato foi assinado durante a manutenção do ERP", "problem": "O sistema que libera a próxima etapa está indisponível no momento da assinatura. Um aviso perdido deixa a operação parada.", "action": "A entrega é acompanhada e pode ser tentada novamente, com histórico do que o sistema de destino respondeu.", "value": "O suporte consegue investigar o aviso e recuperar uma entrega que precisa de atenção.", "limit": "A conclusão depende da resposta do destino. Novas tentativas e tratamento de entregas repetidas precisam estar alinhados à integração.", "source": "https://docs.catalisa.app/blocks/webhooks-engine/", "sourceSection": "casos-de-uso-reais"}, "wpp": {"headline": "Conecte o WhatsApp que já faz parte da rotina.", "intro": "Leve mensagens do número utilizado pela empresa para o contexto do atendimento e da operação.", "caseTitle": "A conversa chega ao sistema de propostas", "problem": "O cliente combina informações pelo WhatsApp e a proposta continua sem esse histórico.", "action": "O número é conectado e as mensagens passam a alimentar a jornada, com respostas do sistema quando previstas.", "value": "A equipe pode consultar o contexto da conversa junto do trabalho em andamento.", "limit": "Usa conexão não oficial. Existe risco de suspensão do número pela Meta. Para operações que exigem o canal oficial, avalie WPP Business.", "source": "https://docs.catalisa.app/blocks/wpp/", "sourceSection": "casos-de-uso-reais"}, "wpp-business": {"headline": "Transforme o WhatsApp em parte da operação.", "intro": "Conecte o canal oficial da Meta a mensagens, campanhas e atendimento humano dentro da jornada do cliente.", "caseTitle": "A conversa começa antes do vencimento", "problem": "Uma financeira quer lembrar a parcela e acolher respostas sem esperar o cliente entrar em atraso.", "action": "A régua envia mensagens aprovadas pelo canal oficial e encaminha as respostas para o atendimento.", "value": "A equipe reúne a comunicação e acompanha a continuidade da conversa.", "limit": "Envios dependem das regras da Meta, de aprovação de modelos quando exigida e das condições do canal.", "source": "https://docs.catalisa.app/blocks/wpp-business/", "sourceSection": "casos-de-uso-reais"}};
function bBusinessCase(b,s){return `<section class="b-business-case case-${bDomain(b.category).tone}" id="exemplo"><div class="wrap"><div class="b-case-intro"><span class="label">Na prática / Exemplo de uso</span><h2>${ce(s.caseTitle)}</h2><p>Uma leitura simplificada do cenário apresentado na documentação.</p><span class="b-example-label">Cenário de uso · não é depoimento de cliente</span></div><div class="b-case-story"><article><span>01 / O desafio</span><p>${ce(s.problem)}</p></article><article><span>02 / Com esta capacidade</span><p>${ce(s.action)}</p></article><article class="b-case-value"><span>03 / O valor para a operação</span><p>${ce(s.value)}</p></article></div><div class="b-case-source">${ca(b.source+(s.sourceSection?'#'+s.sourceSection:''),'Explore o exemplo na documentação')}</div></div></section>`}
cBlock=function(b,blocks){const s=B_STORIES[b.slug],d=bDomain(b.category),related=C_PRODUCTS.filter(p=>p.blocks?.includes(b.slug)),siblings=blocks.filter(x=>x.category===b.category&&x.slug!==b.slug).slice(0,3);if(!s)return bDetail(b,blocks);return `<article class="building-detail business-detail bd-${d.tone}"><nav class="wrap breadcrumb" aria-label="Localização"><a href="/capacidades/">Building blocks</a><span>/</span>${ce(b.category)}</nav><header class="b-detail-heading wrap"><div>${cl(b.category+' / Building block')}<h1>${ce(b.name)}</h1><p class="b-business-headline">${ce(s.headline)}</p><p class="b-business-intro">${ce(s.intro)}</p><div class="b-detail-meta">${ca(b.source,'Ver documentação')}<span class="b-row-stage ${b.status==='Produção'?'production':''}">${ce(b.status)}</span></div></div><div class="b-detail-art">${bGlyph(b.category,'business-'+b.slug)}</div><button class="visual-pause" data-visual-pause aria-pressed="false">Ⅱ Pausar movimento</button></header><nav class="b-detail-nav wrap" aria-label="Explore esta capacidade"><a href="#exemplo">Exemplo de uso</a><a href="#valor">Valor para o negócio</a><a href="#contexto">Disponibilidade</a></nav>${bBusinessCase(b,s)}<section class="b-business-value wrap" id="valor"><div><span class="label">O que muda no dia a dia</span><h2>${ce(s.headline)}</h2></div><div><p>${ce(s.value)}</p><p class="b-value-context">A capacidade se conecta às regras e às pessoas da sua operação. O produto define como ela participa da jornada.</p>${ca('/arquitetura/','Entenda como as peças se conectam')}</div></section>${related.length?`<section class="b-product-context wrap"><div><span class="label">A mesma peça, em contexto</span><h2>Veja o negócio<br>ganhar forma.</h2><p>Explore composições que reúnem esta capacidade e outras peças da plataforma.</p></div><div>${related.map(p=>`<a href="/ecossistema/${p.slug}/"><span>${ce(p.category)}</span><h3>${ce(p.name)}</h3><p>${ce(p.principle||p.title)}</p><i aria-hidden="true">↗</i></a>`).join('')}</div></section>`:''}<section class="b-business-context wrap" id="contexto"><div><span class="label">Para avaliar esta capacidade</span><h2>Disponibilidade<br>e contexto.</h2><span class="b-row-stage ${b.status==='Produção'?'production':''}">${ce(b.status)}</span></div><div><p>${ce(s.limit)}</p><p class="b-business-source">Resumo editorial baseado na documentação da capacidade. Exemplos ilustram aplicações possíveis; resultados e disponibilidade dependem da composição e das integrações.</p>${ca(b.source,'Ver escopo e documentação completa')}</div></section>${siblings.length?`<section class="b-siblings wrap"><span class="label">Continue neste domínio</span><div>${siblings.map(x=>`<a href="/capacidades/${x.slug}/"><h3>${ce(x.name)}</h3><p>${ce(B_STORIES[x.slug]?.intro||x.tagline)}</p><span>Explore a capacidade ↗</span></a>`).join('')}</div></section>`:''}</article>`};
